__MATX("xformules",{"res":{"ch":[{"pts":["Score de Glasgow : Glasgow = Yeux (1-4) + Verbal (1-5) + Moteur (1-6)  → total de 3 à 15"],"tabs":[],"imgs":[]},{"pts":["Intervalle entre deux doses : Intervalle (h) = 24 ÷ nombre de prises par 24 h"],"tabs":[],"imgs":[]},{"pts":["Diurèse réelle sous lavage vésical : Diurèse réelle (ml) = volume recueilli − volume de lavage"],"tabs":[],"imgs":[]},{"pts":["Diurèse horaire : Diurèse horaire (ml/h) = volume urinaire (ml) ÷ durée (h)","Diurèse rapportée au poids : Diurèse (ml/kg/h) = volume (ml) ÷ durée (h) ÷ Poids (kg) ; cible CH-5 : 1 ml/kg/h"],"tabs":[],"imgs":[]},{"pts":["N-acétylcystéine orale – dose de charge : Dose (mg) = 140 mg/kg × Poids ; puis 70 mg/kg toutes les 4 h jusqu'à H72","N-acétylcystéine orale – entretien : Dose par prise (mg) = 70 mg/kg × Poids, toutes les 4 h jusqu'à la 72e heure","N-acétylcystéine IV – dose de charge : Dose (mg) = 150 mg/kg × Poids en 1 h ; puis 50 mg/kg en 4 h ; puis 100 mg/kg en 15 h","Dose ingérée de paracétamol en mg/kg : Dose (mg/kg) = quantité ingérée (mg) ÷ Poids (kg)","Seuil toxique du paracétamol (adulte) : Seuil minimal (mg) = 125 mg/kg × Poids (seuil fixe cité : 10 g chez l'adulte)"],"tabs":[],"imgs":[]},{"pts":["Seuil toxique de l'aspirine chez l'enfant : Seuil (g) = 0,15 g/kg × Poids","Hydratation de l'enfant intoxiqué à l'aspirine (150 ml/kg/24 h) : Volume (ml/24 h) = 150 ml/kg × Poids (G10 ; idem bicarbonate 14 ‰)","Mannitol 10 % par injection (30 ml/kg/24 h en 3 fois) : Volume par injection (ml) = 30 ml/kg × Poids ÷ 3"],"tabs":[],"imgs":[]},{"pts":["Atropine – dose initiale (organophosphorés) : Dose (mg) = 0,03 mg/kg × Poids","Atropine – entretien : Débit (mg/h) = 0,02 mg/kg/h × Poids","Pralidoxime – bolus : Bolus (mg) = 30 mg/kg × Poids ; puis 8 mg/kg/h","Pralidoxime – entretien : Débit (mg/h) = 8 mg/kg/h × Poids"],"tabs":[],"imgs":[]},{"pts":["Débit de perfusion (gouttes/min) : Débit (gouttes/min) = Volume (ml) × 20 ÷ durée (min)   [perfuseur standard 20 gouttes/ml]"],"tabs":[],"imgs":[]},{"pts":["Score d'Apgar : Apgar = Aspect + Pouls + Grimace + Activité + Respiration (0-2 chacun) → total sur 10, à 1, 5 et 10 min"],"tabs":[],"imgs":[]},{"pts":["Règle des 9 de Wallace : SCB (%) = somme des zones brûlées : tête-cou 9, chaque membre sup. 9, chaque face du tronc 18, chaque membre inf. 18, OGE 1","Table de Lund et Browder : SCB (%) = somme des zones (valeurs selon l'âge : tête 19/17/13/10/7 ; cuisse 5,5/6,5/8,5/8,5/9,5 ; jambe 5/5/5,5/6/7 ; autres zones fixes)","Règle d'Evans – Q1 (grosses molécules) : Q1 (ml) = 1 ml × Poids (kg) × SCB (%)","Règle d'Evans – total du 1er jour (Q1 + Q2) : Q2 = Q1 + 2 000 ml ; Total J1 = Q1 + Q2 = 2 × P × SCB + 2 000 (ml) ; J2 = moitié","Evans – part de bicarbonate 14 ‰ dans Q2 : Bicarbonate 14 ‰ = Q2 ÷ 4 (le reste, ¾, en glucosé)","Règle de Baxter (J1) : J1 (ml) = Poids (kg) × 4 × SCB (%) ; J2 = ½ de J1","Perfusion immédiate du brûlé (1re heure) : 1re heure : 150 ml par 10 kg de poids (grosses molécules) → V = 150 × P ÷ 10 ; puis 300 ml/10 kg sur les 5 h suivantes","Perfusion du brûlé (5 heures suivantes) : 5 heures suivantes : 300 ml par 10 kg (solutés surtout alcalins) → V = 300 × P ÷ 10","Pronostic du brûlé (âge + étendue) : Indice = âge (ans) + SCB (%)"],"tabs":[],"imgs":[]},{"pts":["Enfants de 0 à 11 mois : PC = 4% × Pt  →  Pt = PC / 0,04","Enfants de 1 à 4 ans : PC = 17,32% × Pt  →  Pt = PC / 0,1732","Enfants de 0 à 5 ans / 0 à 59 mois : PC = 20% × Pt  →  Pt = PC / 0,20","Femmes en âge de reproduction (FAR) : FAR = 20% × Pt  →  Pt = FAR / 0,20","Femmes enceintes : PC = 5% × Pt  →  Pt = PC / 0,05","Naissances attendues : PC = 3,5% × Pt  →  Pt = PC / 0,035","Femmes en postnatal : Nombre = 4,7% × Pt","Jeunes filles de 9 ans : PC = 45% × Pt  →  Pt = PC / 0,45"],"tabs":[],"imgs":[]},{"pts":["Population moyenne (Pop M) : Pop M = (population de départ + population d'arrivée) / 2","Taux brut de natalité (TBN) : TBN = (naissances vivantes / population totale ou moyenne) × 100","Taux d'accouchement assisté (TAcc A) : TAcc A = (femmes assistées / accouchements attendus) × 100","Taux général de fécondité (TGF) : TGF = (naissances vivantes de l'année / nombre de FAR) × 100","Taux d'accroissement naturel (TAN) : TAN = [(naissances - décès) / population début d'année] × 100 ; ou TAN = TBN - TBM","Taux d'accroissement annuel (TAA) : TAA = [(population fin d'année - population début d'année) / population début d'année] × 100","Équation fondamentale de population : Pt = P0 + (N - D) + (I - E)","Projection démographique : Pt = P0 (1 + r)^t","Calcul de r sur un an : r = (Pt / P0) - 1","Temps de dédoublement (TD/TDD) : TD = 70 / TAA","Année de dédoublement (AD) : AD = AR + TD"],"tabs":[],"imgs":[]},{"pts":["Taux brut de morbidité (TBM) : TBM = (personnes malades / population totale ou moyenne) × 100","Taux d'incidence (TI) : TI = (nouveaux cas / population totale ou moyenne) × 100","Taux de prévalence (TP) : TP = [(anciens cas + nouveaux cas) / population totale ou moyenne] × 100","Taux brut de mortalité (TBM) : TBM = (décès / population totale ou moyenne) × 100","Taux de mortalité spécifique (TMS) : TMS = (décès dus à la cause étudiée / population totale ou moyenne) × 100","Taux de létalité (TL) : TL = (décès causés par la maladie / total des cas de cette maladie) × 100"],"tabs":[],"imgs":[]},{"pts":["Taux de mortalité infantile (TMI) : TMI = (décès 0-11 mois / naissances vivantes) × 1 000","Taux de mortalité juvénile (TMJ) : TMJ = (décès 1-4 ans / effectif total 1-4 ans) × 100","Taux de mortalité maternelle (TMM) : TMM = (décès maternels / naissances vivantes) × 100","Taux de mortalité néonatale (TMNN) : TMNN = (décès 0-28 jours / naissances vivantes) × 100","Mortalité néonatale précoce (TMNNP) : TMNNP = (décès 0 à <8 jours / naissances vivantes) × 100","Mortalité néonatale tardive (TMNNT) : TMNNT = (décès 8 à <28 jours / naissances vivantes) × 100","Mortalité post-néonatale (TMPNN) : TMPNN = (décès 28 jours à 11 mois / naissances vivantes) × 100","Quotient de mortalité à l'âge x (Qx) : Qx = Dx / Sx","Taux générique (Tx) : Tx = événement / population totale"],"tabs":[],"imgs":[]},{"pts":["Taux de perte (TP) : TP = [(doses sorties - doses administrées)/doses sorties] × 100 ; TP = 100 - TU","Taux d'utilisation (TU) : TU = (doses administrées / doses sorties) × 100 ; TU = 100 - TP","Facteur de perte (FP) : FP = 100 / (100 - TP)","Besoin théorique pour une période (BT) : BT = [PC × objectif × contacts × FP × période] / 12","Stock de sécurité des vaccins (SS) : SS = BT × 25 / 100","Stock de sécurité des consommables (SS) : SS = BT × 10 / 100","Besoin réel (BR) : BR = BT + SS","Quantité à commander (QC) : QC = BR - QS","Besoin annuel (BA) : BA = PC × objectif × contacts × FP","Taux de couverture vaccinale (TCV) : TCV = (doses administrées / population cible) × 100","Taux d'abandon spécifique Penta (TAS) : TAS = [(Penta1 - Penta3)/Penta1] × 100","Taux d'abandon spécifique Td (TAS) : TAS = [(Td1 - Td2)/Td1] × 100","Taux d'abandon global (TAG) : TAG = [(Penta1 - RR)/Penta1] × 100","Seringues d'injection : Nombre de seringues = nombre de doses à administrer","Seringues de dilution : 1 seringue de dilution pour 1 flacon à reconstituer","Boîtes de sécurité : 1 boîte de sécurité pour 100 seringues","Besoin annuel en boîtes de sécurité : Boîtes annuelles = seringues annuelles / 100","Besoin mensuel en boîtes de sécurité : Boîtes mensuelles = boîtes annuelles / 12"],"tabs":[],"imgs":[]},{"pts":["Population cible du monitorage (PCM) : PCM = nombre de femmes enceintes / 2","Disponibilité des ressources (DR) : DR = (ressources existantes / ressources requises) × 100","Accessibilité géographique (AG) : AG = [(femmes <5km + femmes stratégie avancée) / PCM] × 100","Utilisation des services (US) : US = (femmes ayant reçu ≥1 dose de fer / PCM) × 100","Couverture adéquate (CA) : CA = (gestantes ayant pris le fer toute la grossesse / PCM) × 100","Couverture effective (CE) : CE = (gestantes selon directives nationales / PCM) × 100"],"tabs":[],"imgs":[]},{"pts":["Fonds d'aide sociale (FAS) : FAS = 10% × recettes brutes","Intéressement du personnel (IP) : IP = 15% × recettes brutes","Salaire du personnel de soutien (SPS) : SPS = 20% × recettes brutes","Total des dépenses du centre (TDC) : TDC = FAS + IP + SPS","Ressources propres (RP) : RP = recettes brutes - TDC","Fonds de réserve (FR) - recettes déjà déposées : FR = SB - recettes des six mois déposées","Fonds de réserve (FR) - intérêts et agios : FR = SB + intérêts - agios","Somme à budgétiser (SAB) : SAB = RVME + RCAS","Répartition de la SAB : SAB = DO + DFL","Dépenses obligatoires (DO) : DO = SAB - DFL","Dépenses de fonctionnement local (DFL) : DFL = SAB - DO","Imprévus (Imp) : Imp = 5% × DFL","Immobilisations (Im) : Im = 10% × DFL","Autres dépenses (ADép) : ADép = 85% × DFL","Intérêts (convention) : Intérêts compris: 0 ; non compris: ajouter (+)","Agios (convention) : Agios compris: soustraire (-) ; non compris: 0"],"tabs":[],"imgs":[]},{"pts":["Taux de promptitude (TP) : TP = (rapports reçus dans le délai / rapports attendus) × 100","Taux de complétude (TC) : TC = (rapports reçus par le responsable CSE / rapports attendus) × 100"],"tabs":[],"imgs":[]},{"pts":["Proportion de femmes (Pf) : Pf = (F / Pt) × 100","Proportion d'hommes (Pm) : Pm = (M / Pt) × 100","Rapport de masculinité (Rm) : Rm = (M / F) × 100","Proportion d'un âge x : Proportion = (Px / Pt) × 100","Densité globale (d) : d = P / S","Densité rurale (drur) : drur = Prur / Srur","Densité agricole (dagr) : dagr = Prur / Sagr","Densité urbaine (durb) : durb = Purb / Surb","Taux d'urbanisation (Txurb) : Txurb = (Purb / P) × 100"],"tabs":[],"imgs":[]}],"comp":[]},"course":{"0":"<h3>Score de Glasgow</h3><p><b>Glasgow = Yeux (1-4) + Verbal (1-5) + Moteur (1-6)  → total de 3 à 15</b></p><p><b>Ouverture des yeux (Y)</b></p><ul><li>4 = Spontanée</li><li>3 = À l'appel / au bruit</li><li>2 = À la douleur</li><li>1 = Nulle</li></ul><p><b>Réponse verbale (V)</b></p><ul><li>5 = Appropriée (orientée)</li><li>4 = Confuse</li><li>3 = Incohérente</li><li>2 = Incompréhensible</li><li>1 = Aucune</li></ul><p><b>Réponse motrice (M)</b></p><ul><li>6 = Sur commande</li><li>5 = Orientée à la douleur</li><li>4 = Retrait</li><li>3 = Flexion anormale (décortication)</li><li>2 = Extension (décérébration)</li><li>1 = Aucune</li></ul><p>➜ 3 à 8 : traumatisme crânien GRAVE → réanimation</p><p>➜ 9 à 12 : traumatisme crânien MODÉRÉ → réanimation / surveillance rapprochée</p><p>➜ 13 à 15 : traumatisme crânien BÉNIN (léger)</p><p>⚠️ <b>Piège :</b> On additionne les 3 cotations : le minimum est 3 (pas 0). Retenir « 4-5-6 » : Yeux 4, Verbal 5, Moteur 6.</p><p>📝 <i>Yeux à la douleur, mots incompréhensibles, flexion anormale.</i><br>✔ 7</p><p>📝 <i>Yeux à l'appel, réponse confuse, retrait à la douleur.</i><br>✔ 11</p><p>📝 <i>Aucune ouverture des yeux, aucune réponse verbale, extension à la douleur.</i><br>✔ 4</p>","1":"<h3>Intervalle entre deux doses</h3><p><b>Intervalle (h) = 24 ÷ nombre de prises par 24 h</b></p><p>⚠️ <b>Piège :</b> 📝 Calcul hors des PDF (le cours prescrit « 4 fois/24 h »).</p><p>📝 <i>4 prises/24 h.</i><br>✔ 6</p><p>📝 <i>3 prises/24 h.</i><br>✔ 8</p><p>📝 <i>2 prises/24 h.</i><br>✔ 12</p>","2":"<h3>Diurèse réelle sous lavage vésical</h3><p><b>Diurèse réelle (ml) = volume recueilli − volume de lavage</b></p><p>⚠️ <b>Piège :</b> 📝 La soustraction n'est pas écrite dans le PDF (la fiche de surveillance p.169 note entrées/sorties).</p><p>📝 <i>11 800 ml recueillis, 9 000 ml de lavage.</i><br>✔ 2800</p><p>📝 <i>6 500 ml, 5 000 ml.</i><br>✔ 1500</p><p>📝 <i>9 200 ml, 7 000 ml.</i><br>✔ 2200</p>","3":"<h3>Diurèse horaire</h3><p><b>Diurèse horaire (ml/h) = volume urinaire (ml) ÷ durée (h)</b></p><p>➜ &lt; 20 ml/h : oligurie → prévenir le médecin</p><p>➜ 20-50 ml/h : correct selon CH-5 (20-30 cc/h) mais sous l'objectif de 50 ml/h des cours de traumatologie (⚠ D07)</p><p>➜ ≥ 50 ml/h : objectif atteint selon tous les cours</p><p>⚠️ <b>Piège :</b> ⚠ Objectif : 50 ml/h (CH-2/CH-3) ou 20-30 ml/h / 1 ml/kg (CH-5).</p><p>📝 <i>180 ml en 4 h.</i><br>✔ 45</p><p>📝 <i>300 ml en 6 h.</i><br>✔ 50</p><p>📝 <i>60 ml en 3 h.</i><br>✔ 20</p><h3>Diurèse rapportée au poids</h3><p><b>Diurèse (ml/kg/h) = volume (ml) ÷ durée (h) ÷ Poids (kg) ; cible CH-5 : 1 ml/kg/h</b></p><p>➜ &lt; 1 ml/kg/h : sous la référence « 1 ml/kg » (CH-5)</p><p>➜ ≥ 1 ml/kg/h : référence atteinte</p><p>⚠️ <b>Piège :</b> Diviser d'abord par le nombre d'heures, puis par le poids.</p><p>📝 <i>180 ml en 6 h, 50 kg.</i><br>✔ 0.6</p><p>📝 <i>420 ml en 6 h, 70 kg.</i><br>✔ 1</p><p>📝 <i>240 ml en 4 h, 60 kg.</i><br>✔ 1</p>","4":"<h3>N-acétylcystéine orale – dose de charge</h3><p><b>Dose (mg) = 140 mg/kg × Poids ; puis 70 mg/kg toutes les 4 h jusqu'à H72</b></p><p>⚠️ <b>Piège :</b> Dose de charge 140, entretien 70 : la deuxième est la moitié de la première.</p><p>📝 <i>60 kg.</i><br>✔ 8400</p><p>📝 <i>50 kg.</i><br>✔ 7000</p><p>📝 <i>75 kg.</i><br>✔ 10500</p><h3>N-acétylcystéine orale – entretien</h3><p><b>Dose par prise (mg) = 70 mg/kg × Poids, toutes les 4 h jusqu'à la 72e heure</b></p><p>⚠️ <b>Piège :</b> Toutes les 4 h, pas toutes les 6 h.</p><p>📝 <i>50 kg.</i><br>✔ 3500</p><p>📝 <i>60 kg.</i><br>✔ 4200</p><p>📝 <i>80 kg.</i><br>✔ 5600</p><h3>N-acétylcystéine IV – dose de charge</h3><p><b>Dose (mg) = 150 mg/kg × Poids en 1 h ; puis 50 mg/kg en 4 h ; puis 100 mg/kg en 15 h</b></p><p>⚠️ <b>Piège :</b> IV : 150 – 50 – 100 ; orale : 140 – 70.</p><p>📝 <i>70 kg.</i><br>✔ 10500</p><p>📝 <i>60 kg.</i><br>✔ 9000</p><p>📝 <i>50 kg.</i><br>✔ 7500</p><h3>Dose ingérée de paracétamol en mg/kg</h3><p><b>Dose (mg/kg) = quantité ingérée (mg) ÷ Poids (kg)</b></p><p>➜ &lt; 100 mg/kg : en dessous des seuils toxiques cités</p><p>➜ 100-150 mg/kg : seuil toxique chez l'enfant → médecin</p><p>➜ ≥ 125 mg/kg : dose toxique (adulte 125-150 mg/kg ou 10 g) → médecin, NAC</p><p>⚠️ <b>Piège :</b> Toujours rapporter au poids : 1,5 g chez un enfant de 12 kg est déjà toxique.</p><p>📝 <i>Enfant de 12 kg, 1 500 mg.</i><br>✔ 125</p><p>📝 <i>Adulte de 60 kg, 9 000 mg.</i><br>✔ 150</p><p>📝 <i>Enfant de 20 kg, 1 000 mg.</i><br>✔ 50</p><h3>Seuil toxique du paracétamol (adulte)</h3><p><b>Seuil minimal (mg) = 125 mg/kg × Poids (seuil fixe cité : 10 g chez l'adulte)</b></p><p>⚠️ <b>Piège :</b> Le cours donne 125-150 mg/kg ; 10 g chez l'adulte ; 100-150 mg/kg chez l'enfant.</p><p>📝 <i>64 kg.</i><br>✔ 8000</p><p>📝 <i>80 kg.</i><br>✔ 10000</p><p>📝 <i>48 kg.</i><br>✔ 6000</p>","5":"<h3>Seuil toxique de l'aspirine chez l'enfant</h3><p><b>Seuil (g) = 0,15 g/kg × Poids</b></p><p>⚠️ <b>Piège :</b> 0,15 g/kg = 150 mg/kg.</p><p>📝 <i>18 kg.</i><br>✔ 2.7</p><p>📝 <i>10 kg.</i><br>✔ 1.5</p><p>📝 <i>30 kg.</i><br>✔ 4.5</p><h3>Hydratation de l'enfant intoxiqué à l'aspirine (150 ml/kg/24 h)</h3><p><b>Volume (ml/24 h) = 150 ml/kg × Poids (G10 ; idem bicarbonate 14 ‰)</b></p><p>⚠️ <b>Piège :</b> G10 et bicarbonate 14 ‰ : 150 ml/kg/24 h chacun ; mannitol 10 % : 30 ml/kg/24 h.</p><p>📝 <i>14 kg.</i><br>✔ 2100</p><p>📝 <i>10 kg.</i><br>✔ 1500</p><p>📝 <i>22 kg.</i><br>✔ 3300</p><h3>Mannitol 10 % par injection (30 ml/kg/24 h en 3 fois)</h3><p><b>Volume par injection (ml) = 30 ml/kg × Poids ÷ 3</b></p><p>⚠️ <b>Piège :</b> Diviser le total des 24 h par 3 injections.</p><p>📝 <i>20 kg.</i><br>✔ 200</p><p>📝 <i>12 kg.</i><br>✔ 120</p><p>📝 <i>30 kg.</i><br>✔ 300</p>","6":"<h3>Atropine – dose initiale (organophosphorés)</h3><p><b>Dose (mg) = 0,03 mg/kg × Poids</b></p><p>⚠️ <b>Piège :</b> Le cours arrondit à « 2 mg » chez l'adulte.</p><p>📝 <i>70 kg.</i><br>✔ 2.1</p><p>📝 <i>50 kg.</i><br>✔ 1.5</p><p>📝 <i>60 kg.</i><br>✔ 1.8</p><h3>Atropine – entretien</h3><p><b>Débit (mg/h) = 0,02 mg/kg/h × Poids</b></p><p>⚠️ <b>Piège :</b> Entretien pendant 24 h voire plusieurs jours, adapté aux signes d'atropinisation.</p><p>📝 <i>60 kg.</i><br>✔ 1.2</p><p>📝 <i>50 kg.</i><br>✔ 1.0</p><p>📝 <i>80 kg.</i><br>✔ 1.6</p><h3>Pralidoxime – bolus</h3><p><b>Bolus (mg) = 30 mg/kg × Poids ; puis 8 mg/kg/h</b></p><p>⚠️ <b>Piège :</b> Bolus 30 mg/kg, entretien 8 mg/kg/h.</p><p>📝 <i>50 kg.</i><br>✔ 1500</p><p>📝 <i>60 kg.</i><br>✔ 1800</p><p>📝 <i>70 kg.</i><br>✔ 2100</p><h3>Pralidoxime – entretien</h3><p><b>Débit (mg/h) = 8 mg/kg/h × Poids</b></p><p>⚠️ <b>Piège :</b> Ne pas confondre avec le bolus (30 mg/kg).</p><p>📝 <i>50 kg.</i><br>✔ 400</p><p>📝 <i>60 kg.</i><br>✔ 480</p><p>📝 <i>75 kg.</i><br>✔ 600</p>","7":"<h3>Débit de perfusion (gouttes/min)</h3><p><b>Débit (gouttes/min) = Volume (ml) × 20 ÷ durée (min)   [perfuseur standard 20 gouttes/ml]</b></p><p>⚠️ <b>Piège :</b> 📝 Formule hors des PDF. Convertir les heures en minutes (4 h = 240 min).</p><p>📝 <i>1 000 ml en 4 h (240 min).</i><br>✔ 83.3</p><p>📝 <i>500 ml en 2 h (120 min).</i><br>✔ 83.3</p><p>📝 <i>1 500 ml en 6 h (360 min).</i><br>✔ 83.3</p>","8":"<h3>Score d'Apgar</h3><p><b>Apgar = Aspect + Pouls + Grimace + Activité + Respiration (0-2 chacun) → total sur 10, à 1, 5 et 10 min</b></p><p><b>Aspect (coloration)</b></p><ul><li>2 = Rose partout</li><li>1 = Cyanose des extrémités</li><li>0 = Cyanose / pâleur généralisée</li></ul><p><b>Pouls (FC)</b></p><ul><li>2 = &gt; 100/min</li><li>1 = &lt; 100/min</li><li>0 = Absent</li></ul><p><b>Grimace (réactivité)</b></p><ul><li>2 = Cri</li><li>1 = Grimace / geignement</li><li>0 = Absence</li></ul><p><b>Activité (tonus)</b></p><ul><li>2 = Quadriflexion</li><li>1 = Flexion des extrémités</li><li>0 = Hypotonie</li></ul><p><b>Respiration</b></p><ul><li>2 = Régulière</li><li>1 = Irrégulière</li><li>0 = Absente</li></ul><p>➜ &lt; 3 : souffrance sévère / mort apparente → appel urgent pédiatre + réanimateur</p><p>➜ 3 à 7 : souffrance modérée → sécher, aspirer, ventiler au masque, O2</p><p>➜ &gt; 7 : absence de souffrance → soins normaux, mise au sein</p><p>⚠️ <b>Piège :</b> Le cours écrit « somme des 3 cotes » : il s'agit en réalité de la somme des 5 critères (à vérifier auprès de l'enseignant).</p><p>📝 <i>Cyanose des extrémités, FC 90/min, grimace, flexion des extrémités, respiration irrégulière.</i><br>✔ 5</p><p>📝 <i>Rose partout, FC 120/min, cri, quadriflexion, respiration régulière.</i><br>✔ 10</p><p>📝 <i>Pâleur généralisée, FC 80/min, aucune réaction, hypotonie, respiration absente.</i><br>✔ 1</p>","9":"<h3>Règle des 9 de Wallace</h3><p><b>SCB (%) = somme des zones brûlées : tête-cou 9, chaque membre sup. 9, chaque face du tronc 18, chaque membre inf. 18, OGE 1</b></p><p>Tête et cou · 9</p><p>Membre supérieur droit · 9</p><p>Membre supérieur gauche · 9</p><p>Tronc – face antérieure · 18</p><p>Tronc – face postérieure · 18</p><p>Membre inférieur droit · 18</p><p>Membre inférieur gauche · 18</p><p>Organes génitaux externes · 1</p><p>➜ &lt; 10 % : brûlure limitée (soins locaux) — attention, chez l'enfant le seuil d'étendue est plus bas (⚠ D16)</p><p>➜ 10-15 % : grave chez l'enfant (&gt; 10 %, CH-4 p.86)</p><p>➜ ≥ 15 % : brûlure grave/étendue chez l'adulte → réanimation</p><p>➜ &gt; 30 % : pronostic très réservé</p><p>➜ ≥ 75 % : très étendue — mort précoce avec anurie</p><p>⚠️ <b>Piège :</b> Le tronc compte 18 % PAR face (36 % au total) et chaque membre inférieur 18 %. Réservée à l'adulte : chez l'enfant, utiliser Lund et Browder.</p><p>📝 <i>Tête-cou et les deux membres supérieurs.</i><br>✔ 27</p><p>📝 <i>Face antérieure du tronc et membre inférieur droit.</i><br>✔ 36</p><p>📝 <i>Les deux membres inférieurs et les organes génitaux externes.</i><br>✔ 37</p><h3>Table de Lund et Browder</h3><p><b>SCB (%) = somme des zones (valeurs selon l'âge : tête 19/17/13/10/7 ; cuisse 5,5/6,5/8,5/8,5/9,5 ; jambe 5/5/5,5/6/7 ; autres zones fixes)</b></p><p>⚠️ <b>Piège :</b> Chez l'enfant, la tête est proportionnellement plus grande : ne pas appliquer les 9 % de Wallace.</p><p>📝 <i>Nourrisson (0-1 an) : tête entière + cou.</i><br>✔ 21</p><p>📝 <i>Enfant de 10-15 ans : les deux cuisses.</i><br>✔ 17</p><p>📝 <i>Enfant de 5-9 ans : 1/3 des deux fesses + un avant-bras.</i><br>✔ 4.7</p><h3>Règle d'Evans – Q1 (grosses molécules)</h3><p><b>Q1 (ml) = 1 ml × Poids (kg) × SCB (%)</b></p><p>⚠️ <b>Piège :</b> Q1 = grosses molécules du 1er jour ; la moitié du total passe dans les 8 premières heures.</p><p>📝 <i>Brûlé de 60 kg, 30 % de SCB.</i><br>✔ 1800</p><p>📝 <i>Brûlé de 50 kg, 20 %.</i><br>✔ 1000</p><p>📝 <i>Enfant de 25 kg, 12 %.</i><br>✔ 300</p><h3>Règle d'Evans – total du 1er jour (Q1 + Q2)</h3><p><b>Q2 = Q1 + 2 000 ml ; Total J1 = Q1 + Q2 = 2 × P × SCB + 2 000 (ml) ; J2 = moitié</b></p><p>⚠️ <b>Piège :</b> Q2 = Q1 + ration de base 2 000 ml (¼ bicarbonate 14 ‰, ¾ glucosé). Ne pas oublier d'additionner Q1.</p><p>📝 <i>60 kg, 30 %.</i><br>✔ 5600</p><p>📝 <i>70 kg, 25 %.</i><br>✔ 5500</p><p>📝 <i>50 kg, 40 %.</i><br>✔ 6000</p><h3>Evans – part de bicarbonate 14 ‰ dans Q2</h3><p><b>Bicarbonate 14 ‰ = Q2 ÷ 4 (le reste, ¾, en glucosé)</b></p><p>⚠️ <b>Piège :</b> ¼ de bicarbonate et ¾ de glucosé : ne pas inverser.</p><p>📝 <i>Q2 = 3 800 ml.</i><br>✔ 950</p><p>📝 <i>Q2 = 4 000 ml.</i><br>✔ 1000</p><p>📝 <i>Q2 = 3 000 ml.</i><br>✔ 750</p><h3>Règle de Baxter (J1)</h3><p><b>J1 (ml) = Poids (kg) × 4 × SCB (%) ; J2 = ½ de J1</b></p><p>⚠️ <b>Piège :</b> Le cours la dit « la plus utilisée aujourd'hui » (p.100) alors que p.94 présente Evans : vérifie laquelle ton enseignant attend.</p><p>📝 <i>70 kg, 20 %.</i><br>✔ 5600</p><p>📝 <i>60 kg, 30 %.</i><br>✔ 7200</p><p>📝 <i>50 kg, 15 %.</i><br>✔ 3000</p><h3>Perfusion immédiate du brûlé (1re heure)</h3><p><b>1re heure : 150 ml par 10 kg de poids (grosses molécules) → V = 150 × P ÷ 10 ; puis 300 ml/10 kg sur les 5 h suivantes</b></p><p>⚠️ <b>Piège :</b> « Faisant fi du pourcentage » : ces règles immédiates ne dépendent que du poids.</p><p>📝 <i>50 kg.</i><br>✔ 750</p><p>📝 <i>70 kg.</i><br>✔ 1050</p><p>📝 <i>20 kg.</i><br>✔ 300</p><h3>Perfusion du brûlé (5 heures suivantes)</h3><p><b>5 heures suivantes : 300 ml par 10 kg (solutés surtout alcalins) → V = 300 × P ÷ 10</b></p><p>⚠️ <b>Piège :</b> 300 ml/10 kg pour l'ensemble des 5 heures, pas par heure.</p><p>📝 <i>50 kg.</i><br>✔ 1500</p><p>📝 <i>60 kg.</i><br>✔ 1800</p><p>📝 <i>30 kg.</i><br>✔ 900</p><h3>Pronostic du brûlé (âge + étendue)</h3><p><b>Indice = âge (ans) + SCB (%)</b></p><p>➜ &lt; 50 : guérison « infiniment probable »</p><p>➜ 50 à 100 : une chance sur deux de guérison</p><p>➜ &gt; 100 : mort quasi certaine</p><p>⚠️ <b>Piège :</b> Toute tare préexistante altère le pronostic, quel que soit l'indice.</p><p>📝 <i>40 ans, 35 %.</i><br>✔ 75</p><p>📝 <i>20 ans, 15 %.</i><br>✔ 35</p><p>📝 <i>70 ans, 45 %.</i><br>✔ 115</p>","10":"<h3>Enfants de 0 à 11 mois</h3><p><b>PC = 4% × Pt  →  Pt = PC / 0,04</b></p><p>4% de la population totale</p><p>📝 <i>La population totale d'une aire sanitaire est de 25 000 habitants. Calculez la population cible des enfants de 0 à 11 mois.</i><br>✔ PC = 0,04 × 25 000 = 1 000. → 1 000 personnes</p><p>📝 <i>La population cible des enfants de 0 à 11 mois est estimée à 1 200 personnes. Retrouver la population totale.</i><br>✔ Pt = 1 200 ÷ 0,04 = 30 000 habitants. → 30 000 habitants</p><p>📝 <i>Un district compte 32 500 habitants. Estimez les enfants de 0 à 11 mois.</i><br>✔ Cible = 32 500 × 0,04 = 1 300. → 1 300 personnes</p><h3>Enfants de 1 à 4 ans</h3><p><b>PC = 17,32% × Pt  →  Pt = PC / 0,1732</b></p><p>📝 <i>La population totale d'une aire sanitaire est de 25 000 habitants. Calculez la population cible des enfants de 1 à 4 ans.</i><br>✔ PC = 0,1732 × 25 000 = 4 330. → 4 330 personnes</p><p>📝 <i>La population cible des enfants de 1 à 4 ans est estimée à 1 732 personnes. Retrouver la population totale.</i><br>✔ Pt = 1 732 ÷ 0,1732 = 10 000 habitants. → 10 000 habitants</p><p>📝 <i>Un district compte 15 000 habitants. Estimez les enfants de 1 à 4 ans.</i><br>✔ Cible = 15 000 × 0,1732 = 2 598. → 2 598 personnes</p><h3>Enfants de 0 à 5 ans / 0 à 59 mois</h3><p><b>PC = 20% × Pt  →  Pt = PC / 0,20</b></p><p>📝 <i>La population totale d'une aire sanitaire est de 18 000 habitants. Calculez la population cible des enfants de 0 à 5 ans.</i><br>✔ PC = 0,2 × 18 000 = 3 600. → 3 600 personnes</p><p>📝 <i>La population cible des enfants de 0 à 5 ans est estimée à 3 600 personnes. Retrouver la population totale.</i><br>✔ Pt = 3 600 ÷ 0,2 = 18 000 habitants. → 18 000 habitants</p><p>📝 <i>Un district compte 23 500 habitants. Estimez les enfants de 0 à 5 ans.</i><br>✔ Cible = 23 500 × 0,2 = 4 700. → 4 700 personnes</p><h3>Femmes en âge de reproduction (FAR)</h3><p><b>FAR = 20% × Pt  →  Pt = FAR / 0,20</b></p><p>📝 <i>La population totale d'une aire sanitaire est de 18 000 habitants. Calculez la population des FAR.</i><br>✔ FAR = 0,2 × 18 000 = 3 600. → 3 600 personnes</p><p>📝 <i>La population cible des FAR est estimée à 3 600 personnes. Retrouver la population totale.</i><br>✔ Pt = 3 600 ÷ 0,2 = 18 000 habitants. → 18 000 habitants</p><p>📝 <i>Un district compte 23 500 habitants. Estimez les FAR.</i><br>✔ Cible = 23 500 × 0,2 = 4 700. → 4 700 personnes</p><h3>Femmes enceintes</h3><p><b>PC = 5% × Pt  →  Pt = PC / 0,05</b></p><p>📝 <i>La population totale d'une aire sanitaire est de 24 000 habitants. Calculez la population cible des femmes enceintes.</i><br>✔ PC = 0,05 × 24 000 = 1 200. → 1 200 personnes</p><p>📝 <i>La population cible des femmes enceintes est estimée à 1 250 personnes. Retrouver la population totale.</i><br>✔ Pt = 1 250 ÷ 0,05 = 25 000 habitants. → 25 000 habitants</p><p>📝 <i>Un district compte 18 600 habitants. Estimez les femmes enceintes.</i><br>✔ Cible = 18 600 × 0,05 = 930. → 930 personnes</p><h3>Naissances attendues</h3><p><b>PC = 3,5% × Pt  →  Pt = PC / 0,035</b></p><p>📝 <i>La population totale d'une aire sanitaire est de 20 000 habitants. Calculez les naissances attendues.</i><br>✔ PC = 0,035 × 20 000 = 700. → 700 personnes</p><p>📝 <i>Les naissances attendues sont estimées à 875 personnes. Retrouver la population totale.</i><br>✔ Pt = 875 ÷ 0,035 = 25 000 habitants. → 25 000 habitants</p><p>📝 <i>Un district compte 32 000 habitants. Estimez les naissances attendues.</i><br>✔ Cible = 32 000 × 0,035 = 1 120. → 1 120 personnes</p><h3>Femmes en postnatal</h3><p><b>Nombre = 4,7% × Pt</b></p><p>📝 <i>La population totale d'une aire sanitaire est de 20 000 habitants. Calculez les femmes en postnatal.</i><br>✔ PC = 0,047 × 20 000 = 940. → 940 personnes</p><p>📝 <i>Les femmes en postnatal sont estimées à 940 personnes. Retrouver la population totale.</i><br>✔ Pt = 940 ÷ 0,047 = 20 000 habitants. → 20 000 habitants</p><p>📝 <i>Un district compte 30 000 habitants. Estimez les femmes en postnatal.</i><br>✔ Cible = 30 000 × 0,047 = 1 410. → 1 410 personnes</p><h3>Jeunes filles de 9 ans</h3><p><b>PC = 45% × Pt  →  Pt = PC / 0,45</b></p><p>Libellé retenu car présent dans deux supports ⚠ SP-2 p.26 : 45 % = enfants de 9 mois à 14 ans ; jeunes filles de 9 ans = 1,86 %.</p><p>📝 <i>La population totale d'une aire sanitaire est de 12 000 habitants. Calculez les jeunes filles de 9 ans.</i><br>✔ PC = 0,45 × 12 000 = 5 400. → 5 400 personnes</p><p>📝 <i>Les jeunes filles de 9 ans sont estimées à 5 400 personnes. Retrouver la population totale.</i><br>✔ Pt = 5 400 ÷ 0,45 = 12 000 habitants. → 12 000 habitants</p><p>📝 <i>Un district compte 8 600 habitants. Estimez les jeunes filles de 9 ans.</i><br>✔ Cible = 8 600 × 0,45 = 3 870. → 3 870 personnes</p>","11":"<h3>Population moyenne (Pop M)</h3><p><b>Pop M = (population de départ + population d'arrivée) / 2</b></p><p>📝 <i>Une population passe de 48 000 à 52 000 habitants en un an. Calculez la population moyenne.</i><br>✔ Pop M = (48 000+52 000)÷2 = 50 000. → 50 000 habitants</p><p>📝 <i>La population moyenne est de 35 000 habitants et la population de départ était de 32 000. Déterminez la population d'arrivée.</i><br>✔ Arrivée = 2×35 000-32 000 = 38 000. → 38 000 habitants</p><p>📝 <i>Une ville avait 72 500 habitants au début et 75 900 à la fin. Calculez sa population moyenne.</i><br>✔ Pop M = (72 500+75 900)÷2 = 74 200. → 74 200 habitants</p><h3>Taux brut de natalité (TBN)</h3><p><b>TBN = (naissances vivantes / population totale ou moyenne) × 100</b></p><p>📝 <i>Une zone enregistre 900 naissances vivantes pour 30 000 habitants. Calculez le TBN.</i><br>✔ (900÷30 000)×100 = 3%. → 3 %</p><p>📝 <i>Le TBN est de 3,5% pour 20 000 habitants. Déterminez le nombre de naissances vivantes.</i><br>✔ (3,5×20 000)÷100 = 700. → 700 naissances</p><p>📝 <i>On dénombre 700 naissances vivantes et le TBN est de 2,8%. Calculez la population totale.</i><br>✔ (700×100)÷2,8 = 25 000. → 25 000 habitants</p><h3>Taux d'accouchement assisté (TAcc A)</h3><p><b>TAcc A = (femmes assistées / accouchements attendus) × 100</b></p><p>Notation choisie pour éviter la confusion avec le TAA</p><p>📝 <i>Une zone enregistre 720 accouchements assistés pour 900 attendus. Calculez le TAcc A.</i><br>✔ (720÷900)×100 = 80%. → 80 %</p><p>📝 <i>Le TAcc A est de 85% pour 1 200 accouchements attendus. Déterminez le nombre d'accouchements assistés.</i><br>✔ (85×1 200)÷100 = 1 020. → 1 020 accouchements</p><p>📝 <i>On dénombre 680 accouchements assistés et le TAcc A est de 80%. Calculez les accouchements attendus.</i><br>✔ (680×100)÷80 = 850. → 850 accouchements</p><h3>Taux général de fécondité (TGF)</h3><p><b>TGF = (naissances vivantes de l'année / nombre de FAR) × 100</b></p><p>📝 <i>Une zone enregistre 840 naissances vivantes pour 12 000 FAR. Calculez le TGF.</i><br>✔ (840÷12 000)×100 = 7%. → 7 %</p><p>📝 <i>Le TGF est de 6% pour 15 000 FAR. Déterminez le nombre de naissances vivantes.</i><br>✔ (6×15 000)÷100 = 900. → 900 naissances</p><p>📝 <i>On dénombre 900 naissances vivantes et le TGF est de 7,5%. Calculez le nombre de FAR.</i><br>✔ (900×100)÷7,5 = 12 000. → 12 000 FAR</p><h3>Taux d'accroissement naturel (TAN)</h3><p><b>TAN = [(naissances - décès) / population début d'année] × 100 ; ou TAN = TBN - TBM</b></p><p>📝 <i>Une localité compte 40 000 habitants au début de l'année, avec 1 600 naissances et 600 décès. Calculez le TAN.</i><br>✔ [(1 600-600)÷40 000]×100 = 2,5%. → 2,5 %</p><p>📝 <i>Population de début = 50 000, TAN = 2%, 400 décès. Déterminez le nombre de naissances.</i><br>✔ Accroissement=1 000 ; naissances=1 000+400=1 400. → 1 400 naissances</p><p>📝 <i>Le TBN d'une zone est 4,2% et le TBM 1,3%. Calculez le TAN par la méthode abrégée.</i><br>✔ TAN = 4,2-1,3 = 2,9%. → 2,9 %</p><h3>Taux d'accroissement annuel (TAA)</h3><p><b>TAA = [(population fin d'année - population début d'année) / population début d'année] × 100</b></p><p>📝 <i>Une population passe de 80 000 à 82 400 habitants en un an. Calculez le TAA.</i><br>✔ [(82 400-80 000)÷80 000]×100 = 3%. → 3 %</p><p>📝 <i>Une commune compte 60 000 habitants au début, TAA=2,5%. Calculez la population de fin d'année.</i><br>✔ 60 000+1 500 = 61 500. → 61 500 habitants</p><p>📝 <i>La population finale est 105 000 après +5% annuel. Retrouver la population de départ.</i><br>✔ 105 000÷1,05 = 100 000. → 100 000 habitants</p><h3>Équation fondamentale de population</h3><p><b>Pt = P0 + (N - D) + (I - E)</b></p><p>N=naissances, D=décès, I=immigrés, E=émigrés</p><p>📝 <i>Une ville compte 50 000 habitants au départ, 1 800 naissances, 700 décès, 900 immigrés, 500 émigrés. Calculez la population finale.</i><br>✔ 50 000+(1 800-700)+(900-500) = 51 500. → 51 500 habitants</p><p>📝 <i>P0=30 000, Pt=30 900, N=1 000, D=400, E=300. Déterminez le nombre d'immigrés I.</i><br>✔ 30 900=30 300+I → I=600. → 600 immigrés</p><p>📝 <i>Une localité passe de 75 000 à 75 800, avec 2 000 naissances, 1 100 décès, 600 immigrés. Calculez le nombre d'émigrés.</i><br>✔ 75 800=76 500-E → E=700. → 700 émigrés</p><h3>Projection démographique</h3><p><b>Pt = P0 (1 + r)^t</b></p><p>r=TAA en décimal, t=durée</p><p>📝 <i>Population initiale de 20 000 habitants, croissance de 3%/an pendant 2 ans. Calculez la population projetée.</i><br>✔ 20 000×1,03² = 21 218. → 21 218 habitants</p><p>📝 <i>Après 2 ans à 10%/an, une population atteint 12 100 habitants. Retrouver la population initiale.</i><br>✔ 12 100÷1,21 = 10 000. → 10 000 habitants</p><p>📝 <i>Une commune de 50 000 habitants augmente de 2%/an. Calculez la population après 3 ans.</i><br>✔ 50 000×1,02³ ≈ 53 060. → 53 060 habitants</p><h3>Calcul de r sur un an</h3><p><b>r = (Pt / P0) - 1</b></p><p>📝 <i>Une population passe de 25 000 à 26 250 habitants en un an. Calculez r (en %).</i><br>✔ r=(26 250÷25 000)-1=0,05 soit 5%. → 5 %</p><p>📝 <i>P0=40 000, r=0,04 pendant un an. Calculez Pt.</i><br>✔ Pt=40 000×1,04=41 600. → 41 600 habitants</p><p>📝 <i>Population finale de 72 000 résulte d'un accroissement de 2,5% en un an. Retrouver P0.</i><br>✔ 72 000÷1,025 ≈ 70 244. → 70 244 habitants</p><h3>Temps de dédoublement (TD/TDD)</h3><p><b>TD = 70 / TAA</b></p><p>TAA exprimé en pourcentage</p><p>📝 <i>Le TAA d'une population est de 2%. Calculez son temps de dédoublement.</i><br>✔ TD=70÷2=35 ans. → 35 ans</p><p>📝 <i>Une population double approximativement en 28 ans. Estimez son TAA.</i><br>✔ TAA=70÷28=2,5%. → 2,5 %</p><p>📝 <i>La zone A a un TAA de 1,4%. Calculez son TD.</i><br>✔ TD=70÷1,4=50 ans. → 50 ans</p><h3>Année de dédoublement (AD)</h3><p><b>AD = AR + TD</b></p><p>AR=année de référence</p><p>📝 <i>Année de référence 2026, temps de dédoublement 35 ans. Calculez l'année de dédoublement.</i><br>✔ AD=2026+35=2061. → 2 061</p><p>📝 <i>Population devant doubler en 2054, référence 2024. Calculez le TD.</i><br>✔ TD=2054-2024=30 ans. → 30 ans</p><p>📝 <i>TD=25 ans, AD=2060. Retrouver l'année de référence.</i><br>✔ AR=2060-25=2035. → 2 035</p>","12":"<h3>Taux brut de morbidité (TBM)</h3><p><b>TBM = (personnes malades / population totale ou moyenne) × 100</b></p><p>📝 <i>Une zone enregistre 525 personnes malades pour 15 000 habitants. Calculez le TBM.</i><br>✔ (525÷15 000)×100=3,5%. → 3,5 %</p><p>📝 <i>Le TBM est de 4% pour 20 000 habitants. Déterminez le nombre de malades.</i><br>✔ (4×20 000)÷100=800. → 800 malades</p><p>📝 <i>600 malades avec un TBM de 3%. Calculez la population totale.</i><br>✔ (600×100)÷3=20 000. → 20 000 habitants</p><h3>Taux d'incidence (TI)</h3><p><b>TI = (nouveaux cas / population totale ou moyenne) × 100</b></p><p>📝 <i>180 nouveaux cas pour 12 000 personnes exposées. Calculez le TI.</i><br>✔ (180÷12 000)×100=1,5%. → 1,5 %</p><p>📝 <i>TI de 2,5% pour 20 000 personnes exposées. Déterminez le nombre de nouveaux cas.</i><br>✔ (2,5×20 000)÷100=500. → 500 cas</p><p>📝 <i>450 nouveaux cas avec un TI de 3%. Calculez la population exposée.</i><br>✔ (450×100)÷3=15 000. → 15 000 personnes</p><h3>Taux de prévalence (TP)</h3><p><b>TP = [(anciens cas + nouveaux cas) / population totale ou moyenne] × 100</b></p><p>📝 <i>750 cas existants pour 25 000 habitants. Calculez le TP.</i><br>✔ (750÷25 000)×100=3%. → 3 %</p><p>📝 <i>TP de 4% pour 30 000 habitants. Déterminez le nombre de cas existants.</i><br>✔ (4×30 000)÷100=1 200. → 1 200 cas</p><p>📝 <i>900 cas existants avec un TP de 3%. Calculez la population totale.</i><br>✔ (900×100)÷3=30 000. → 30 000 habitants</p><h3>Taux brut de mortalité (TBM)</h3><p><b>TBM = (décès / population totale ou moyenne) × 100</b></p><p>📝 <i>240 décès pour 30 000 habitants. Calculez le TBM.</i><br>✔ (240÷30 000)×100=0,8%. → 0,8 %</p><p>📝 <i>TBM de 1,2% pour 25 000 habitants. Déterminez le nombre de décès.</i><br>✔ (1,2×25 000)÷100=300. → 300 décès</p><p>📝 <i>300 décès avec un TBM de 1%. Calculez la population totale.</i><br>✔ (300×100)÷1=30 000. → 30 000 habitants</p><h3>Taux de mortalité spécifique (TMS)</h3><p><b>TMS = (décès dus à la cause étudiée / population totale ou moyenne) × 100</b></p><p>📝 <i>90 décès dus à la maladie pour 30 000 habitants. Calculez le TMS.</i><br>✔ (90÷30 000)×100=0,3%. → 0,3 %</p><p>📝 <i>TMS de 0,5% pour 40 000 habitants. Déterminez le nombre de décès dus à la maladie.</i><br>✔ (0,5×40 000)÷100=200. → 200 décès</p><p>📝 <i>120 décès avec un TMS de 0,4%. Calculez la population totale.</i><br>✔ (120×100)÷0,4=30 000. → 30 000 habitants</p><h3>Taux de létalité (TL)</h3><p><b>TL = (décès causés par la maladie / total des cas de cette maladie) × 100</b></p><p>📝 <i>24 décès pour 600 cas de la maladie. Calculez le TL.</i><br>✔ (24÷600)×100=4%. → 4 %</p><p>📝 <i>TL de 5% pour 800 cas. Déterminez le nombre de décès.</i><br>✔ (5×800)÷100=40. → 40 décès</p><p>📝 <i>30 décès avec un TL de 6%. Calculez le nombre de cas.</i><br>✔ (30×100)÷6=500. → 500 cas</p>","13":"<h3>Taux de mortalité infantile (TMI)</h3><p><b>TMI = (décès 0-11 mois / naissances vivantes) × 1 000</b></p><p>📝 <i>40 décès de 0-11 mois pour 4 000 naissances vivantes. Calculez le TMI.</i><br>✔ (40÷4 000)×1 000=10‰. → 10 ‰</p><p>📝 <i>TMI de 15‰ pour 6 000 naissances vivantes. Déterminez le nombre de décès.</i><br>✔ (15×6 000)÷1 000=90. → 90 décès</p><p>📝 <i>45 décès avec un TMI de 15‰. Calculez le nombre de naissances vivantes.</i><br>✔ (45×1 000)÷15=3 000. → 3 000 naissances</p><h3>Taux de mortalité juvénile (TMJ)</h3><p><b>TMJ = (décès 1-4 ans / effectif total 1-4 ans) × 100</b></p><p>📝 <i>35 décès pour 7 000 enfants de 1-4 ans. Calculez le TMJ.</i><br>✔ (35÷7 000)×100=0,5%. → 0,5 %</p><p>📝 <i>TMJ de 0,8% pour 10 000 enfants. Déterminez le nombre de décès.</i><br>✔ (0,8×10 000)÷100=80. → 80 décès</p><p>📝 <i>60 décès avec un TMJ de 0,6%. Calculez l'effectif d'enfants de 1-4 ans.</i><br>✔ (60×100)÷0,6=10 000. → 10 000 enfants</p><h3>Taux de mortalité maternelle (TMM)</h3><p><b>TMM = (décès maternels / naissances vivantes) × 100</b></p><p>⚠ SP-2 p.34 multiplie par 100 000 (TMM pour 100 000 naissances vivantes).</p><p>📝 <i>12 décès maternels pour 6 000 naissances vivantes. Calculez le TMM.</i><br>✔ (12÷6 000)×100=0,2%. → 0,2 %</p><p>📝 <i>TMM de 0,15% pour 8 000 naissances vivantes. Déterminez le nombre de décès maternels.</i><br>✔ (0,15×8 000)÷100=12. → 12 décès</p><p>📝 <i>15 décès maternels avec un TMM de 0,2%. Calculez le nombre de naissances vivantes.</i><br>✔ (15×100)÷0,2=7 500. → 7 500 naissances</p><h3>Taux de mortalité néonatale (TMNN)</h3><p><b>TMNN = (décès 0-28 jours / naissances vivantes) × 100</b></p><p>📝 <i>30 décès de 0-28 jours pour 3 000 naissances vivantes. Calculez le TMNN.</i><br>✔ (30÷3 000)×100=1%. → 1 %</p><p>📝 <i>TMNN de 1,5% pour 4 000 naissances vivantes. Déterminez le nombre de décès.</i><br>✔ (1,5×4 000)÷100=60. → 60 décès</p><p>📝 <i>45 décès avec un TMNN de 1,5%. Calculez le nombre de naissances vivantes.</i><br>✔ (45×100)÷1,5=3 000. → 3 000 naissances</p><h3>Mortalité néonatale précoce (TMNNP)</h3><p><b>TMNNP = (décès 0 à &lt;8 jours / naissances vivantes) × 100</b></p><p>📝 <i>18 décès de 0 à &lt;8 jours pour 3 000 naissances vivantes. Calculez le TMNNP.</i><br>✔ (18÷3 000)×100=0,6%. → 0,6 %</p><p>📝 <i>TMNNP de 0,8% pour 5 000 naissances vivantes. Déterminez le nombre de décès.</i><br>✔ (0,8×5 000)÷100=40. → 40 décès</p><p>📝 <i>24 décès avec un TMNNP de 0,6%. Calculez le nombre de naissances vivantes.</i><br>✔ (24×100)÷0,6=4 000. → 4 000 naissances</p><h3>Mortalité néonatale tardive (TMNNT)</h3><p><b>TMNNT = (décès 8 à &lt;28 jours / naissances vivantes) × 100</b></p><p>📝 <i>12 décès de 8 à &lt;28 jours pour 3 000 naissances vivantes. Calculez le TMNNT.</i><br>✔ (12÷3 000)×100=0,4%. → 0,4 %</p><p>📝 <i>TMNNT de 0,4% pour 5 000 naissances vivantes. Déterminez le nombre de décès.</i><br>✔ (0,4×5 000)÷100=20. → 20 décès</p><p>📝 <i>20 décès avec un TMNNT de 0,5%. Calculez le nombre de naissances vivantes.</i><br>✔ (20×100)÷0,5=4 000. → 4 000 naissances</p><h3>Mortalité post-néonatale (TMPNN)</h3><p><b>TMPNN = (décès 28 jours à 11 mois / naissances vivantes) × 100</b></p><p>📝 <i>24 décès de 28 jours à 11 mois pour 4 000 naissances vivantes. Calculez le TMPNN.</i><br>✔ (24÷4 000)×100=0,6%. → 0,6 %</p><p>📝 <i>TMPNN de 0,7% pour 6 000 naissances vivantes. Déterminez le nombre de décès.</i><br>✔ (0,7×6 000)÷100=42. → 42 décès</p><p>📝 <i>35 décès avec un TMPNN de 0,5%. Calculez le nombre de naissances vivantes.</i><br>✔ (35×100)÷0,5=7 000. → 7 000 naissances</p><h3>Quotient de mortalité à l'âge x (Qx)</h3><p><b>Qx = Dx / Sx</b></p><p>Dx=décès à l'âge x, Sx=survivants</p><p>📝 <i>25 décès parmi 5 000 survivants. Calculez Qx.</i><br>✔ Qx=25÷5 000=0,005. → 0,005</p><p>📝 <i>Qx=0,008, Sx=4 000. Déterminez Dx.</i><br>✔ Dx=0,008×4 000=32. → 32 décès</p><p>📝 <i>18 décès, Qx=0,006. Calculez Sx.</i><br>✔ Sx=18÷0,006=3 000. → 3 000 survivants</p><h3>Taux générique (Tx)</h3><p><b>Tx = événement / population totale</b></p><p>Appliquer le multiplicateur indiqué</p><p>📝 <i>45 événements dans une population de 1 500 personnes, résultat en pourcentage. Calculez Tx.</i><br>✔ 45÷1 500=0,03 → 3%. → 3 %</p><p>📝 <i>Taux générique de 20 pour 1 000 dans 8 000 personnes. Combien d'événements ?</i><br>✔ 20×8 000÷1 000=160. → 160 événements</p><p>📝 <i>72 événements, taux de 12 pour 1 000. Calculez la population totale.</i><br>✔ 72×1 000÷12=6 000. → 6 000 personnes</p>","14":"<h3>Taux de perte (TP)</h3><p><b>TP = [(doses sorties - doses administrées)/doses sorties] × 100 ; TP = 100 - TU</b></p><p>📝 <i>1 000 doses sorties, 850 administrées. Calculez le TP.</i><br>✔ [(1 000-850)÷1 000]×100=15%. → 15 %</p><p>📝 <i>Le TU d'un vaccin est de 92%. Calculez son TP.</i><br>✔ TP=100-92=8%. → 8 %</p><p>📝 <i>TP de 12% pour 2 500 doses sorties. Calculez les doses perdues.</i><br>✔ 2 500×12%=300. → 300 doses</p><h3>Taux d'utilisation (TU)</h3><p><b>TU = (doses administrées / doses sorties) × 100 ; TU = 100 - TP</b></p><p>📝 <i>1 200 doses sorties, 1 080 administrées. Calculez le TU.</i><br>✔ (1 080÷1 200)×100=90%. → 90 %</p><p>📝 <i>Le TP est de 7%. Calculez le TU.</i><br>✔ TU=100-7=93%. → 93 %</p><p>📝 <i>TU de 88% pour 2 000 doses sorties. Calculez les doses administrées.</i><br>✔ 2 000×88%=1 760. → 1 760 doses</p><h3>Facteur de perte (FP)</h3><p><b>FP = 100 / (100 - TP)</b></p><p>📝 <i>Le TP d'un vaccin est de 20%. Calculez le FP.</i><br>✔ FP=100÷(100-20)=1,25. → 1,25</p><p>📝 <i>Le TP est de 10%. Calculez FP (2 décimales).</i><br>✔ FP=100÷90≈1,11. → 1,11</p><p>📝 <i>Le FP est de 1,25. Retrouver le TP.</i><br>✔ 100-TP=100÷1,25=80 → TP=20%. → 20 %</p><h3>Besoin théorique pour une période (BT)</h3><p><b>BT = [PC × objectif × contacts × FP × période] / 12</b></p><p>période en mois</p><p>📝 <i>PC=1 000, objectif=80%, 3 contacts, FP=1,25, période=6 mois. Calculez BT.</i><br>✔ (1 000×0,80×3×1,25×6)÷12=1 500. → 1 500 doses</p><p>📝 <i>BT=2 400 doses pour 8 mois, objectif=80%, 3 contacts, FP=1,25. Calculez PC.</i><br>✔ (2 400×12)÷(0,80×3×1,25×8)=1 200. → 1 200 personnes</p><p>📝 <i>PC=1 500, objectif=80%, 2 contacts, FP=1,25, BT=2 250. Déterminez la période (mois).</i><br>✔ (2 250×12)÷(1 500×0,80×2×1,25)=9. → 9 mois</p><h3>Stock de sécurité des vaccins (SS)</h3><p><b>SS = BT × 25 / 100</b></p><p>📝 <i>BT=4 000 doses. Calculez le SS.</i><br>✔ 4 000×25÷100=1 000. → 1 000 doses</p><p>📝 <i>SS=750 doses. Retrouver BT.</i><br>✔ 750×100÷25=3 000. → 3 000 doses</p><p>📝 <i>BT=2 400 doses. Calculez le SS.</i><br>✔ 2 400×25%=600. → 600 doses</p><h3>Stock de sécurité des consommables (SS)</h3><p><b>SS = BT × 10 / 100</b></p><p>📝 <i>BT=5 000 unités. Calculez le SS.</i><br>✔ 5 000×10÷100=500. → 500 unités</p><p>📝 <i>SS=280 unités. Retrouver BT.</i><br>✔ 280×100÷10=2 800. → 2 800 unités</p><p>📝 <i>BT mensuel=3 500 unités. Calculez le SS.</i><br>✔ 3 500×10%=350. → 350 unités</p><h3>Besoin réel (BR)</h3><p><b>BR = BT + SS</b></p><p>📝 <i>BT=3 200 doses, SS=800 doses. Calculez BR.</i><br>✔ 3 200+800=4 000. → 4 000 doses</p><p>📝 <i>BR=5 500, BT=4 400. Calculez SS.</i><br>✔ 5 500-4 400=1 100. → 1 100 doses</p><p>📝 <i>BT=6 000, SS=25% du BT. Calculez BR.</i><br>✔ SS=1 500 ; BR=6 000+1 500=7 500. → 7 500 doses</p><h3>Quantité à commander (QC)</h3><p><b>QC = BR - QS</b></p><p>QS=quantité en stock</p><p>📝 <i>BR=4 500 doses, stock disponible=1 200. Calculez QC.</i><br>✔ 4 500-1 200=3 300. → 3 300 doses</p><p>📝 <i>QC=2 700, BR=4 000. Calculez QS.</i><br>✔ 4 000-2 700=1 300. → 1 300 doses</p><p>📝 <i>BT=3 600, SS=900, QS=1 500. Calculez QC.</i><br>✔ BR=4 500 ; QC=4 500-1 500=3 000. → 3 000 doses</p><h3>Besoin annuel (BA)</h3><p><b>BA = PC × objectif × contacts × FP</b></p><p>📝 <i>PC=1 000, objectif=90%, 3 contacts, FP=1,25. Calculez BA.</i><br>✔ 1 000×0,90×3×1,25=3 375. → 3 375 doses</p><p>📝 <i>BA=4 500, objectif=80%, 3 contacts, FP=1,25. Calculez PC.</i><br>✔ 4 500÷(0,80×3×1,25)=1 500. → 1 500 personnes</p><p>📝 <i>PC=2 000, objectif=75%, FP=1,20, BA=5 400. Déterminez le nombre de contacts.</i><br>✔ 5 400÷(2 000×0,75×1,20)=3. → 3 contacts</p><h3>Taux de couverture vaccinale (TCV)</h3><p><b>TCV = (doses administrées / population cible) × 100</b></p><p>📝 <i>850 doses administrées pour 1 000 personnes cibles. Calculez le TCV.</i><br>✔ (850÷1 000)×100=85%. → 85 %</p><p>📝 <i>TCV de 90% pour 1 500 personnes cibles. Déterminez les doses administrées.</i><br>✔ (90×1 500)÷100=1 350. → 1 350 doses</p><p>📝 <i>720 doses administrées avec un TCV de 80%. Calculez la population cible.</i><br>✔ (720×100)÷80=900. → 900 personnes</p><h3>Taux d'abandon spécifique Penta (TAS)</h3><p><b>TAS = [(Penta1 - Penta3)/Penta1] × 100</b></p><p>📝 <i>Penta1=1 000, Penta3=850. Calculez le TAS.</i><br>✔ [(1 000-850)÷1 000]×100=15%. → 15 %</p><p>📝 <i>Penta1=1 200, TAS=10%. Calculez Penta3.</i><br>✔ Abandons=120 ; Penta3=1 080. → 1 080 enfants</p><p>📝 <i>Penta3=900, TAS=10%. Retrouver Penta1.</i><br>✔ Penta1=900÷0,90=1 000. → 1 000 enfants</p><h3>Taux d'abandon spécifique Td (TAS)</h3><p><b>TAS = [(Td1 - Td2)/Td1] × 100</b></p><p>📝 <i>Td1=800, Td2=680. Calculez le TAS.</i><br>✔ [(800-680)÷800]×100=15%. → 15 %</p><p>📝 <i>Td1=1 000, TAS=8%. Calculez Td2.</i><br>✔ Abandons=80 ; Td2=920. → 920 femmes</p><p>📝 <i>Td2=855, TAS=5%. Retrouver Td1.</i><br>✔ Td1=855÷0,95=900. → 900 femmes</p><h3>Taux d'abandon global (TAG)</h3><p><b>TAG = [(Penta1 - RR)/Penta1] × 100</b></p><p>RR=vaccin rougeole-rubéole</p><p>📝 <i>Penta1=1 000, RR=780. Calculez le TAG.</i><br>✔ [(1 000-780)÷1 000]×100=22%. → 22 %</p><p>📝 <i>Penta1=1 500, TAG=20%. Calculez le nombre d'enfants ayant reçu RR.</i><br>✔ Abandons=300 ; RR=1 200. → 1 200 enfants</p><p>📝 <i>RR=900, TAG=10%. Retrouver Penta1.</i><br>✔ Penta1=900÷0,90=1 000. → 1 000 enfants</p><h3>Seringues d'injection</h3><p><b>Nombre de seringues = nombre de doses à administrer</b></p><p>📝 <i>1 250 doses à administrer. Combien de seringues d'injection ?</i><br>✔ 1 seringue = 1 dose : 1 250. → 1 250 seringues</p><p>📝 <i>Un centre possède 900 seringues d'injection. Combien de doses max ?</i><br>✔ 1 seringue = 1 dose : 900. → 900 doses</p><p>📝 <i>Deux campagnes prévoient 1 400 et 1 850 doses. Besoin total en seringues ?</i><br>✔ 1 400+1 850=3 250. → 3 250 seringues</p><h3>Seringues de dilution</h3><p><b>1 seringue de dilution pour 1 flacon à reconstituer</b></p><p>📝 <i>180 flacons à reconstituer. Combien de seringues de dilution ?</i><br>✔ 1 seringue par flacon : 180. → 180 seringues</p><p>📝 <i>250 seringues de dilution disponibles. Combien de flacons max ?</i><br>✔ 250 flacons. → 250 flacons</p><p>📝 <i>Trois sites doivent reconstituer 120, 95 et 135 flacons. Besoin total en seringues de dilution ?</i><br>✔ 120+95+135=350. → 350 seringues</p><h3>Boîtes de sécurité</h3><p><b>1 boîte de sécurité pour 100 seringues</b></p><p>📝 <i>Combien de boîtes de sécurité pour 1 200 seringues ?</i><br>✔ 1 200÷100=12. → 12 boîtes</p><p>📝 <i>18 boîtes de sécurité disponibles. Combien de seringues peuvent-elles contenir ?</i><br>✔ 18×100=1 800. → 1 800 seringues</p><p>📝 <i>2 400 seringues d'injection + 600 de dilution. Nombre total de boîtes ?</i><br>✔ 3 000÷100=30. → 30 boîtes</p><h3>Besoin annuel en boîtes de sécurité</h3><p><b>Boîtes annuelles = seringues annuelles / 100</b></p><p>📝 <i>Besoin annuel de 4 800 seringues. Calculez les boîtes annuelles.</i><br>✔ 4 800÷100=48. → 48 boîtes</p><p>📝 <i>Besoin annuel de 72 boîtes. Retrouver le nombre de seringues.</i><br>✔ 72×100=7 200. → 7 200 seringues</p><p>📝 <i>3 600 seringues d'injection + 1 200 de dilution par an. Besoin annuel en boîtes ?</i><br>✔ 4 800÷100=48. → 48 boîtes</p><h3>Besoin mensuel en boîtes de sécurité</h3><p><b>Boîtes mensuelles = boîtes annuelles / 12</b></p><p>📝 <i>Besoin annuel de 60 boîtes. Calculez le besoin mensuel.</i><br>✔ 60÷12=5. → 5 boîtes/mois</p><p>📝 <i>Un centre utilise 8 boîtes par mois. Calculez son besoin annuel.</i><br>✔ 8×12=96. → 96 boîtes</p><p>📝 <i>Besoin annuel en seringues de 7 200. Calculez les boîtes mensuelles.</i><br>✔ 7 200÷100=72 ; 72÷12=6. → 6 boîtes/mois</p>","15":"<h3>Population cible du monitorage (PCM)</h3><p><b>PCM = nombre de femmes enceintes / 2</b></p><p>📝 <i>Une aire sanitaire compte 1 200 femmes enceintes. Calculez la PCM.</i><br>✔ 1 200÷2=600. → 600 femmes</p><p>📝 <i>PCM=450 femmes. Retrouver le nombre de femmes enceintes.</i><br>✔ 450×2=900. → 900 femmes</p><p>📝 <i>Deux secteurs comptent 800 et 1 000 femmes enceintes. Calculez la PCM totale.</i><br>✔ 1 800÷2=900. → 900 femmes</p><h3>Disponibilité des ressources (DR)</h3><p><b>DR = (ressources existantes / ressources requises) × 100</b></p><p>Le fer est cité comme exemple</p><p>📝 <i>720 unités existantes pour 800 requises. Calculez le DR.</i><br>✔ (720÷800)×100=90%. → 90 %</p><p>📝 <i>DR de 85% pour 1 200 unités requises. Déterminez les unités existantes.</i><br>✔ (85×1 200)÷100=1 020. → 1 020 unités</p><p>📝 <i>680 unités existantes avec un DR de 80%. Calculez les unités requises.</i><br>✔ (680×100)÷80=850. → 850 unités</p><h3>Accessibilité géographique (AG)</h3><p><b>AG = [(femmes &lt;5km + femmes stratégie avancée) / PCM] × 100</b></p><p>📝 <i>PCM=1 000. 650 femmes à moins de 5 km, 150 en stratégie avancée. Calculez AG.</i><br>✔ [(650+150)÷1 000]×100=80%. → 80 %</p><p>📝 <i>AG=75%, PCM=1 200, 700 femmes à moins de 5 km. Combien en stratégie avancée ?</i><br>✔ 900-700=200. → 200 femmes</p><p>📝 <i>900 femmes à moins de 5 km, 180 en stratégie avancée, PCM=1 200. Calculez AG.</i><br>✔ 1 080÷1 200×100=90%. → 90 %</p><h3>Utilisation des services (US)</h3><p><b>US = (femmes ayant reçu ≥1 dose de fer / PCM) × 100</b></p><p>📝 <i>720 femmes ayant reçu du fer pour 900 femmes de la PCM. Calculez le US.</i><br>✔ (720÷900)×100=80%. → 80 %</p><p>📝 <i>US de 85% pour 1 200 femmes de la PCM. Déterminez le nombre de femmes ayant reçu du fer.</i><br>✔ (85×1 200)÷100=1 020. → 1 020 femmes</p><p>📝 <i>680 femmes ayant reçu du fer avec un US de 80%. Calculez la PCM.</i><br>✔ (680×100)÷80=850. → 850 femmes</p><h3>Couverture adéquate (CA)</h3><p><b>CA = (gestantes ayant pris le fer toute la grossesse / PCM) × 100</b></p><p>📝 <i>630 gestantes pour 900 femmes de la PCM. Calculez le CA.</i><br>✔ (630÷900)×100=70%. → 70 %</p><p>📝 <i>CA de 75% pour 1 200 femmes de la PCM. Déterminez le nombre de gestantes.</i><br>✔ (75×1 200)÷100=900. → 900 gestantes</p><p>📝 <i>680 gestantes avec un CA de 80%. Calculez la PCM.</i><br>✔ (680×100)÷80=850. → 850 femmes</p><h3>Couverture effective (CE)</h3><p><b>CE = (gestantes selon directives nationales / PCM) × 100</b></p><p>📝 <i>540 gestantes ayant suivi les directives pour 900 femmes de la PCM. Calculez le CE.</i><br>✔ (540÷900)×100=60%. → 60 %</p><p>📝 <i>CE de 70% pour 1 200 femmes de la PCM. Déterminez le nombre de gestantes.</i><br>✔ (70×1 200)÷100=840. → 840 gestantes</p><p>📝 <i>560 gestantes avec un CE de 80%. Calculez la PCM.</i><br>✔ (560×100)÷80=700. → 700 femmes</p>","16":"<h3>Fonds d'aide sociale (FAS)</h3><p><b>FAS = 10% × recettes brutes</b></p><p>📝 <i>Recettes brutes de 800 000 F CFA. Calculez le FAS.</i><br>✔ 10%×800 000=80 000. → 80 000 F CFA</p><p>📝 <i>FAS de 150 000 F CFA (10%). Calculez les recettes brutes.</i><br>✔ 150 000×100÷10=1 500 000. → 1 500 000 F CFA</p><p>📝 <i>Recettes brutes de 1 250 000 F CFA. Calculez le FAS.</i><br>✔ 1 250 000×10÷100=125 000. → 125 000 F CFA</p><h3>Intéressement du personnel (IP)</h3><p><b>IP = 15% × recettes brutes</b></p><p>📝 <i>Recettes brutes de 800 000 F CFA. Calculez le IP.</i><br>✔ 15%×800 000=120 000. → 120 000 F CFA</p><p>📝 <i>IP de 150 000 F CFA (15%). Calculez les recettes brutes.</i><br>✔ 150 000×100÷15=1 000 000. → 1 000 000 F CFA</p><p>📝 <i>Recettes brutes de 1 250 000 F CFA. Calculez le IP.</i><br>✔ 1 250 000×15÷100=187 500. → 187 500 F CFA</p><h3>Salaire du personnel de soutien (SPS)</h3><p><b>SPS = 20% × recettes brutes</b></p><p>📝 <i>Recettes brutes de 800 000 F CFA. Calculez le SPS.</i><br>✔ 20%×800 000=160 000. → 160 000 F CFA</p><p>📝 <i>SPS de 150 000 F CFA (20%). Calculez les recettes brutes.</i><br>✔ 150 000×100÷20=750 000. → 750 000 F CFA</p><p>📝 <i>Recettes brutes de 1 250 000 F CFA. Calculez le SPS.</i><br>✔ 1 250 000×20÷100=250 000. → 250 000 F CFA</p><h3>Total des dépenses du centre (TDC)</h3><p><b>TDC = FAS + IP + SPS</b></p><p>📝 <i>FAS=100 000, IP=150 000, SPS=200 000. Calculez TDC.</i><br>✔ 100 000+150 000+200 000=450 000. → 450 000 F CFA</p><p>📝 <i>TDC=540 000, FAS=120 000, IP=180 000. Calculez SPS.</i><br>✔ 540 000-120 000-180 000=240 000. → 240 000 F CFA</p><p>📝 <i>Recettes brutes de 2 000 000 F. Calculez TDC (FAS+IP+SPS=45%).</i><br>✔ 200 000+300 000+400 000=900 000. → 900 000 F CFA</p><h3>Ressources propres (RP)</h3><p><b>RP = recettes brutes - TDC</b></p><p>📝 <i>Recettes brutes 1 500 000 F, TDC 675 000 F. Calculez RP.</i><br>✔ 1 500 000-675 000=825 000. → 825 000 F CFA</p><p>📝 <i>RP=660 000, TDC=540 000. Calculez les recettes brutes.</i><br>✔ 660 000+540 000=1 200 000. → 1 200 000 F CFA</p><p>📝 <i>Recettes brutes de 2 400 000 F, TDC=45%. Calculez RP.</i><br>✔ TDC=1 080 000 ; RP=1 320 000. → 1 320 000 F CFA</p><h3>Fonds de réserve (FR) - recettes déjà déposées</h3><p><b>FR = SB - recettes des six mois déposées</b></p><p>SB=somme à la banque</p><p>📝 <i>SB=3 000 000 F, recettes déposées=1 200 000 F. Calculez FR.</i><br>✔ 3 000 000-1 200 000=1 800 000. → 1 800 000 F CFA</p><p>📝 <i>FR=2 100 000, recettes déposées=900 000. Calculez SB.</i><br>✔ 2 100 000+900 000=3 000 000. → 3 000 000 F CFA</p><p>📝 <i>SB=4 500 000, FR=2 750 000. Calculez les recettes déposées.</i><br>✔ 4 500 000-2 750 000=1 750 000. → 1 750 000 F CFA</p><h3>Fonds de réserve (FR) - intérêts et agios</h3><p><b>FR = SB + intérêts - agios</b></p><p>📝 <i>SB=2 000 000, intérêts=50 000, agios=20 000. Calculez FR.</i><br>✔ 2 000 000+50 000-20 000=2 030 000. → 2 030 000 F CFA</p><p>📝 <i>FR=3 040 000, SB=3 000 000, agios=10 000. Calculez les intérêts.</i><br>✔ 3 040 000-3 000 000+10 000=50 000. → 50 000 F CFA</p><p>📝 <i>SB=4 000 000, intérêts=80 000, FR=4 030 000. Calculez les agios.</i><br>✔ 4 000 000+80 000-4 030 000=50 000. → 50 000 F CFA</p><h3>Somme à budgétiser (SAB)</h3><p><b>SAB = RVME + RCAS</b></p><p>📝 <i>RVME=850 000, RCAS=350 000. Calculez SAB.</i><br>✔ 850 000+350 000=1 200 000. → 1 200 000 F CFA</p><p>📝 <i>SAB=1 500 000, RVME=950 000. Calculez RCAS.</i><br>✔ 1 500 000-950 000=550 000. → 550 000 F CFA</p><p>📝 <i>Ventes de médicaments=1 200 000, actes de santé=40% de ce montant. Calculez SAB.</i><br>✔ RCAS=480 000 ; SAB=1 680 000. → 1 680 000 F CFA</p><h3>Répartition de la SAB</h3><p><b>SAB = DO + DFL</b></p><p>📝 <i>DO=700 000, DFL=300 000. Calculez SAB.</i><br>✔ 700 000+300 000=1 000 000. → 1 000 000 F CFA</p><p>📝 <i>SAB=1 400 000, DO=980 000. Calculez DFL.</i><br>✔ 1 400 000-980 000=420 000. → 420 000 F CFA</p><p>📝 <i>SAB=2 000 000, DFL=30% de SAB. Calculez DFL.</i><br>✔ 2 000 000×30%=600 000. → 600 000 F CFA</p><h3>Dépenses obligatoires (DO)</h3><p><b>DO = SAB - DFL</b></p><p>📝 <i>SAB=1 600 000, DFL=480 000. Calculez DO.</i><br>✔ 1 600 000-480 000=1 120 000. → 1 120 000 F CFA</p><p>📝 <i>DO=900 000, DFL=300 000. Calculez SAB.</i><br>✔ 900 000+300 000=1 200 000. → 1 200 000 F CFA</p><p>📝 <i>SAB=2 500 000, DO=72% de SAB. Calculez DO.</i><br>✔ 2 500 000×72%=1 800 000. → 1 800 000 F CFA</p><h3>Dépenses de fonctionnement local (DFL)</h3><p><b>DFL = SAB - DO</b></p><p>📝 <i>SAB=1 800 000, DO=1 260 000. Calculez DFL.</i><br>✔ 1 800 000-1 260 000=540 000. → 540 000 F CFA</p><p>📝 <i>DFL=450 000, SAB=1 500 000. Calculez DO.</i><br>✔ 1 500 000-450 000=1 050 000. → 1 050 000 F CFA</p><p>📝 <i>DO=1 100 000 (70% de SAB). Calculez SAB.</i><br>✔ 1 100 000÷0,70≈1 571 429. → 1 571 429 F CFA</p><h3>Imprévus (Imp)</h3><p><b>Imp = 5% × DFL</b></p><p>📝 <i>DFL=800 000 F CFA. Calculez les imprévus.</i><br>✔ 5%×800 000=40 000. → 40 000 F CFA</p><p>📝 <i>Imprévus=150 000 F CFA (5%). Calculez les DFL.</i><br>✔ 150 000×100÷5=3 000 000. → 3 000 000 F CFA</p><p>📝 <i>DFL=1 250 000 F CFA. Calculez les imprévus.</i><br>✔ 1 250 000×5÷100=62 500. → 62 500 F CFA</p><h3>Immobilisations (Im)</h3><p><b>Im = 10% × DFL</b></p><p>Le support manuscrit emploie aussi « immeuble »</p><p>📝 <i>DFL=800 000 F CFA. Calculez les immobilisations.</i><br>✔ 10%×800 000=80 000. → 80 000 F CFA</p><p>📝 <i>Immobilisations=150 000 F CFA (10%). Calculez les DFL.</i><br>✔ 150 000×100÷10=1 500 000. → 1 500 000 F CFA</p><p>📝 <i>DFL=1 250 000 F CFA. Calculez les immobilisations.</i><br>✔ 1 250 000×10÷100=125 000. → 125 000 F CFA</p><h3>Autres dépenses (ADép)</h3><p><b>ADép = 85% × DFL</b></p><p>📝 <i>DFL=800 000 F CFA. Calculez les autres dépenses.</i><br>✔ 85%×800 000=680 000. → 680 000 F CFA</p><p>📝 <i>Autres dépenses=150 000 F CFA (85%). Calculez les DFL.</i><br>✔ 150 000×100÷85≈176 471. → 176 471 F CFA</p><p>📝 <i>DFL=1 250 000 F CFA. Calculez les autres dépenses.</i><br>✔ 1 250 000×85÷100=1 062 500. → 1 062 500 F CFA</p><h3>Intérêts (convention)</h3><p><b>Intérêts compris: 0 ; non compris: ajouter (+)</b></p><p>Convention du support manuscrit</p><p>📝 <i>Intérêts de 35 000 F non compris dans une somme bancaire de 1 500 000 F. Montant à retenir ?</i><br>✔ 1 500 000+35 000=1 535 000. → 1 535 000 F CFA</p><p>📝 <i>SB de 2 000 000 F comprend déjà 40 000 F d'intérêts. Montant à ajouter ?</i><br>✔ Intérêts compris → ajout=0. → 0 F CFA</p><p>📝 <i>SB=1 800 000 F, intérêts de 30 000 F non compris. Montant retenu ?</i><br>✔ 1 800 000+30 000=1 830 000. → 1 830 000 F CFA</p><h3>Agios (convention)</h3><p><b>Agios compris: soustraire (-) ; non compris: 0</b></p><p>Convention du support manuscrit</p><p>📝 <i>Une somme de 1 600 000 F comprend des agios de 20 000 F. Montant à retenir ?</i><br>✔ 1 600 000-20 000=1 580 000. → 1 580 000 F CFA</p><p>📝 <i>SB de 2 500 000 F, agios non compris. Montant à soustraire ?</i><br>✔ Agios non compris → 0. → 0 F CFA</p><p>📝 <i>SB=3 000 000 F, intérêts non compris de 60 000 F, agios compris de 25 000 F. Montant corrigé ?</i><br>✔ 3 000 000+60 000-25 000=3 035 000. → 3 035 000 F CFA</p>","17":"<h3>Taux de promptitude (TP)</h3><p><b>TP = (rapports reçus dans le délai / rapports attendus) × 100</b></p><p>📝 <i>45 rapports reçus dans le délai pour 50 attendus. Calculez le TP.</i><br>✔ (45÷50)×100=90%. → 90 %</p><p>📝 <i>TP de 80% pour 60 rapports attendus. Déterminez le nombre de rapports reçus dans le délai.</i><br>✔ (80×60)÷100=48. → 48 rapports</p><p>📝 <i>48 rapports reçus dans le délai avec un TP de 96%. Calculez le nombre de rapports attendus.</i><br>✔ (48×100)÷96=50. → 50 rapports</p><h3>Taux de complétude (TC)</h3><p><b>TC = (rapports reçus par le responsable CSE / rapports attendus) × 100</b></p><p>📝 <i>57 rapports reçus pour 60 attendus. Calculez le TC.</i><br>✔ (57÷60)×100=95%. → 95 %</p><p>📝 <i>TC de 90% pour 80 rapports attendus. Déterminez le nombre de rapports reçus.</i><br>✔ (90×80)÷100=72. → 72 rapports</p><p>📝 <i>72 rapports reçus avec un TC de 80%. Calculez le nombre de rapports attendus.</i><br>✔ (72×100)÷80=90. → 90 rapports</p>","18":"<h3>Proportion de femmes (Pf)</h3><p><b>Pf = (F / Pt) × 100</b></p><p>📝 <i>27 000 femmes pour 50 000 habitants. Calculez le Pf.</i><br>✔ (27 000÷50 000)×100=54%. → 54 %</p><p>📝 <i>Pf de 52% pour 80 000 habitants. Déterminez le nombre de femmes.</i><br>✔ (52×80 000)÷100=41 600. → 41 600 femmes</p><p>📝 <i>33 000 femmes avec un Pf de 55%. Calculez la population totale.</i><br>✔ (33 000×100)÷55=60 000. → 60 000 habitants</p><h3>Proportion d'hommes (Pm)</h3><p><b>Pm = (M / Pt) × 100</b></p><p>📝 <i>24 500 hommes pour 50 000 habitants. Calculez le Pm.</i><br>✔ (24 500÷50 000)×100=49%. → 49 %</p><p>📝 <i>Pm de 48% pour 80 000 habitants. Déterminez le nombre d'hommes.</i><br>✔ (48×80 000)÷100=38 400. → 38 400 hommes</p><p>📝 <i>29 400 hommes avec un Pm de 49%. Calculez la population totale.</i><br>✔ (29 400×100)÷49=60 000. → 60 000 habitants</p><h3>Rapport de masculinité (Rm)</h3><p><b>Rm = (M / F) × 100</b></p><p>📝 <i>48 000 hommes pour 50 000 femmes. Calculez le Rm.</i><br>✔ (48 000÷50 000)×100=96%. → 96 %</p><p>📝 <i>Rm de 96% pour 60 000 femmes. Déterminez le nombre d'hommes.</i><br>✔ (96×60 000)÷100=57 600. → 57 600 hommes</p><p>📝 <i>57 600 hommes avec un Rm de 96%. Calculez le nombre de femmes.</i><br>✔ (57 600×100)÷96=60 000. → 60 000 femmes</p><h3>Proportion d'un âge x</h3><p><b>Proportion = (Px / Pt) × 100</b></p><p>📝 <i>6 000 personnes d'âge x pour 40 000 habitants. Calculez la proportion.</i><br>✔ (6 000÷40 000)×100=15%. → 15 %</p><p>📝 <i>Proportion de 18% pour 50 000 habitants. Déterminez Px.</i><br>✔ (18×50 000)÷100=9 000. → 9 000 personnes</p><p>📝 <i>7 200 personnes d'âge x avec une proportion de 12%. Calculez la population totale.</i><br>✔ (7 200×100)÷12=60 000. → 60 000 habitants</p><h3>Densité globale (d)</h3><p><b>d = P / S</b></p><p>📝 <i>120 000 habitants sur 2 000 km². Calculez la densité globale.</i><br>✔ 120 000÷2 000=60. → 60 hab/km²</p><p>📝 <i>Densité de 80 hab/km² sur 1 500 km². Calculez la population.</i><br>✔ 80×1 500=120 000. → 120 000 habitants</p><p>📝 <i>210 000 habitants, densité de 70 hab/km². Calculez la superficie.</i><br>✔ 210 000÷70=3 000. → 3 000 km²</p><h3>Densité rurale (drur)</h3><p><b>drur = Prur / Srur</b></p><p>📝 <i>Population rurale de 54 000 habitants sur 900 km². Calculez drur.</i><br>✔ 54 000÷900=60. → 60 hab/km²</p><p>📝 <i>drur=75 hab/km², Srur=800 km². Calculez Prur.</i><br>✔ 75×800=60 000. → 60 000 habitants</p><p>📝 <i>Prur=96 000, drur=80 hab/km². Calculez Srur.</i><br>✔ 96 000÷80=1 200. → 1 200 km²</p><h3>Densité agricole (dagr)</h3><p><b>dagr = Prur / Sagr</b></p><p>Sagr=superficie de terre arable</p><p>📝 <i>Population rurale de 45 000 habitants, superficie arable de 500 km². Calculez dagr.</i><br>✔ 45 000÷500=90. → 90 hab/km²</p><p>📝 <i>dagr=120 hab/km², Sagr=400 km². Calculez Prur.</i><br>✔ 120×400=48 000. → 48 000 habitants</p><p>📝 <i>Prur=72 000, dagr=144 hab/km². Calculez Sagr.</i><br>✔ 72 000÷144=500. → 500 km²</p><h3>Densité urbaine (durb)</h3><p><b>durb = Purb / Surb</b></p><p>📝 <i>Une ville compte 180 000 habitants sur 300 km². Calculez durb.</i><br>✔ 180 000÷300=600. → 600 hab/km²</p><p>📝 <i>durb=750 hab/km², Surb=240 km². Calculez Purb.</i><br>✔ 750×240=180 000. → 180 000 habitants</p><p>📝 <i>Purb=250 000, durb=1 000 hab/km². Calculez Surb.</i><br>✔ 250 000÷1 000=250. → 250 km²</p><h3>Taux d'urbanisation (Txurb)</h3><p><b>Txurb = (Purb / P) × 100</b></p><p>📝 <i>60 000 habitants urbains pour 100 000 habitants totaux. Calculez le Txurb.</i><br>✔ (60 000÷100 000)×100=60%. → 60 %</p><p>📝 <i>Txurb de 65% pour 120 000 habitants totaux. Déterminez les habitants urbains.</i><br>✔ (65×120 000)÷100=78 000. → 78 000 habitants</p><p>📝 <i>78 000 habitants urbains avec un Txurb de 60%. Calculez la population totale.</i><br>✔ (78 000×100)÷60=130 000. → 130 000 habitants</p>"},"xd":1});
